import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "discover-probe",
  name: "Discover Probe",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "probe_discover",
        version: "1.0.0",
        description: "调用宿主 discover_tools 列出可用工具，用于探查 emit/事件机制",
        permissions: { capabilities: [] },
        sideEffect: false,
        parameters: {
          type: "object",
          properties: {
            query: { type: "string", description: "可选查询关键字" },
          },
          additionalProperties: true,
        },
        outputSchema: { type: "object" },
        async handler(args: any, tctx: any) {
          const attempts: any[] = [];
          const queries = [
            undefined,
            "emit",
            "event",
            "counter",
          ];
          for (const q of queries) {
            try {
              const res = await tctx.invoke(
                "discover_tools",
                q === undefined ? {} : { query: q }
              );
              attempts.push({ query: q, ok: true, res });
            } catch (e: any) {
              attempts.push({ query: q, ok: false, error: String(e?.message ?? e) });
            }
          }
          return { ok: true, data: { attempts } };
        },
      },
    });
  },
};

export default plugin;

